    static void Main(string[] args)
    {
        // Crée un nouvel objet HttpListener
        HttpListener listener = new HttpListener();

        // Ajoute l'adresse IP et le port à écouter
        listener.Prefixes.Add("http://localhost:8080/hello");

        // Démarre le listener
        listener.Start();

        Console.WriteLine("Server started. Listening on http://localhost:8080/hello...");

        // Boucle infinie pour écouter les requêtes
        while (true)
        {
            HttpListenerContext context = listener.GetContext();
            HttpListenerRequest request = context.Request;
            HttpListenerResponse response = context.Response;

            // Traitement de la requête
            if (request.Url.AbsolutePath == "/hello")
            {
                // Envoi de la réponse
